<?php
$pageTitle="Pedidos RGPD"; $active="dashboard"; require_once "layout-top.php";
$total=(int)$pdo->query("SELECT COUNT(*) FROM dpo_pedidos")->fetchColumn(); $recebidos=(int)$pdo->query("SELECT COUNT(*) FROM dpo_pedidos WHERE estado='recebido'")->fetchColumn(); $analise=(int)$pdo->query("SELECT COUNT(*) FROM dpo_pedidos WHERE estado='em_analise'")->fetchColumn(); $respondidos=(int)$pdo->query("SELECT COUNT(*) FROM dpo_pedidos WHERE estado='respondido'")->fetchColumn(); $pedidos=$pdo->query("SELECT * FROM dpo_pedidos ORDER BY criado_em DESC")->fetchAll(PDO::FETCH_ASSOC);
function estadoDpo($e){return ['recebido'=>'Recebido','em_analise'=>'Em análise','respondido'=>'Respondido','arquivado'=>'Arquivado'][$e]??$e;}
?><style>.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}.stat,.row{background:white;border:1px solid #e5e7eb;border-radius:22px;padding:22px}.stat strong{display:block;color:#242A30;font-size:36px}.row{margin-bottom:12px;display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center}.row h3{margin:0 0 8px;color:#11151B}@media(max-width:900px){.stats,.row{grid-template-columns:1fr}}</style><div class="stats"><div class="stat"><strong><?= $total ?></strong><span>Total</span></div><div class="stat"><strong><?= $recebidos ?></strong><span>Recebidos</span></div><div class="stat"><strong><?= $analise ?></strong><span>Em análise</span></div><div class="stat"><strong><?= $respondidos ?></strong><span>Respondidos</span></div></div><?php foreach($pedidos as $p): ?><div class="row"><div><h3><?= htmlspecialchars($p['nome']) ?></h3><span class="badge"><?= htmlspecialchars($p['codigo']) ?></span><span class="badge"><?= htmlspecialchars(estadoDpo($p['estado'])) ?></span><span class="badge"><?= htmlspecialchars($p['email']) ?></span></div><div><a class="btn" href="ver.php?id=<?= (int)$p['id'] ?>">Ver pedido</a></div></div><?php endforeach; ?><?php if(empty($pedidos)): ?><div class="row">Ainda não existem pedidos RGPD.</div><?php endif; ?><?php require_once "layout-bottom.php"; ?>